-- Normalized MySQL domain schema. Existing JSON state remains untouched.
CREATE TABLE IF NOT EXISTS guilds (guild_id VARCHAR(20) NOT NULL PRIMARY KEY, name VARCHAR(190) NULL, settings JSON NOT NULL, stats JSON NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id VARCHAR(64) NOT NULL PRIMARY KEY, discord_id VARCHAR(20) NOT NULL, username VARCHAR(100) NOT NULL, avatar_url TEXT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uq_users_discord_id (discord_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS discord_members (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, user_id VARCHAR(64) NOT NULL, joined_at DATETIME(3) NULL, verified_at DATETIME(3) NULL, x_follow_verified BOOLEAN NOT NULL DEFAULT FALSE, x_follow_verified_at DATETIME(3) NULL, is_suspicious BOOLEAN NOT NULL DEFAULT FALSE, last_message_at DATETIME(3) NULL, message_count INT NOT NULL DEFAULT 0, profile JSON NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uq_members_guild_user (guild_id,user_id), KEY ix_members_guild_joined (guild_id,joined_at), CONSTRAINT fk_members_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_members_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS roles (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, discord_role_id VARCHAR(20) NULL, name VARCHAR(100) NOT NULL, description TEXT NULL, is_internal BOOLEAN NOT NULL DEFAULT FALSE, is_self_assignable BOOLEAN NOT NULL DEFAULT FALSE, requires_role_id VARCHAR(64) NULL, min_overpoints INT NULL, sort_order INT NOT NULL DEFAULT 0, config JSON NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uq_roles_guild_discord (guild_id,discord_role_id), KEY ix_roles_guild_sort (guild_id,sort_order), CONSTRAINT fk_roles_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_roles_requirement FOREIGN KEY (requires_role_id) REFERENCES roles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS member_roles (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, member_id VARCHAR(64) NOT NULL, role_id VARCHAR(64) NOT NULL, granted_by VARCHAR(20) NULL, granted_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), expires_at DATETIME(3) NULL, UNIQUE KEY uq_member_roles (member_id,role_id), KEY ix_member_roles_guild (guild_id,member_id), CONSTRAINT fk_member_roles_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_member_roles_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE, CONSTRAINT fk_member_roles_role FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS role_history (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, member_id VARCHAR(64) NOT NULL, role_id VARCHAR(64) NULL, action VARCHAR(40) NOT NULL, actor_id VARCHAR(20) NULL, reason TEXT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY ix_role_history_member (guild_id,member_id,created_at), CONSTRAINT fk_role_history_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_role_history_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS permission_groups (id VARCHAR(64) NOT NULL PRIMARY KEY, name VARCHAR(80) NOT NULL, description TEXT NULL, UNIQUE KEY uq_permission_groups_name (name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS permissions (id VARCHAR(64) NOT NULL PRIMARY KEY, group_id VARCHAR(64) NOT NULL, permission_key VARCHAR(120) NOT NULL, description TEXT NULL, UNIQUE KEY uq_permissions_group_key (group_id,permission_key), KEY ix_permissions_key (permission_key), CONSTRAINT fk_permissions_group FOREIGN KEY (group_id) REFERENCES permission_groups(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS internal_team_members (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, member_id VARCHAR(64) NOT NULL, discord_id VARCHAR(20) NOT NULL, username VARCHAR(100) NOT NULL, public_role VARCHAR(100) NOT NULL, job_title VARCHAR(120) NOT NULL, department VARCHAR(100) NOT NULL, responsibilities TEXT NULL, group_id VARCHAR(64) NOT NULL, status ENUM('ACTIVE','INACTIVE','SUSPENDED','REMOVED') NOT NULL DEFAULT 'ACTIVE', added_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uq_team_member (guild_id,member_id), UNIQUE KEY uq_team_discord (guild_id,discord_id), KEY ix_team_group_status (guild_id,group_id,status), CONSTRAINT fk_team_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_team_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE, CONSTRAINT fk_team_group FOREIGN KEY (group_id) REFERENCES permission_groups(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS point_balances (member_id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, overpoints BIGINT NOT NULL DEFAULT 0, overcredits BIGINT NOT NULL DEFAULT 0, community_points BIGINT NOT NULL DEFAULT 0, social_points BIGINT NOT NULL DEFAULT 0, referral_points BIGINT NOT NULL DEFAULT 0, contribution_points BIGINT NOT NULL DEFAULT 0, updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), KEY ix_balances_guild (guild_id), CONSTRAINT fk_balances_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_balances_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS point_transactions (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, member_id VARCHAR(64) NOT NULL, currency ENUM('OVERPOINTS','OVERCREDITS') NOT NULL, category VARCHAR(80) NOT NULL, amount BIGINT NOT NULL, balance_after BIGINT NOT NULL, source VARCHAR(80) NOT NULL, idempotency_key VARCHAR(190) NOT NULL, reason TEXT NULL, actor_id VARCHAR(20) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_point_tx_idempotency (idempotency_key), KEY ix_point_tx_member_date (guild_id,member_id,created_at), CONSTRAINT fk_point_tx_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_point_tx_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campaigns (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, name VARCHAR(190) NOT NULL, description TEXT NOT NULL, objectives TEXT NULL, starts_at DATETIME(3) NOT NULL, ends_at DATETIME(3) NOT NULL, tasks JSON NULL, point_reward INT NOT NULL DEFAULT 0, submission_requirements TEXT NULL, status ENUM('DRAFT','ACTIVE','ENDED','CANCELLED') NOT NULL DEFAULT 'DRAFT', created_by VARCHAR(20) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), KEY ix_campaigns_status (guild_id,status), CONSTRAINT fk_campaigns_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campaign_submissions (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, campaign_id VARCHAR(64) NOT NULL, member_id VARCHAR(64) NOT NULL, content TEXT NOT NULL, category VARCHAR(80) NOT NULL DEFAULT 'social', link_url TEXT NULL, image_url TEXT NULL, status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING', feedback TEXT NULL, points_awarded INT NOT NULL DEFAULT 0, reviewed_by VARCHAR(20) NULL, reviewed_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY ix_submissions_campaign_status (guild_id,campaign_id,status), CONSTRAINT fk_submissions_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_submissions_campaign FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE, CONSTRAINT fk_submissions_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS referrals (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, referrer_member_id VARCHAR(64) NOT NULL, referred_member_id VARCHAR(64) NOT NULL, invite_code VARCHAR(100) NOT NULL, verified BOOLEAN NOT NULL DEFAULT FALSE, verified_at DATETIME(3) NULL, retained_7d BOOLEAN NOT NULL DEFAULT FALSE, became_comrade BOOLEAN NOT NULL DEFAULT FALSE, suspicious BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_referrals_pair (guild_id,referrer_member_id,referred_member_id), KEY ix_referrals_invite (guild_id,invite_code), CONSTRAINT fk_referrals_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_referrals_referrer FOREIGN KEY (referrer_member_id) REFERENCES discord_members(id) ON DELETE CASCADE, CONSTRAINT fk_referrals_referred FOREIGN KEY (referred_member_id) REFERENCES discord_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS referral_invites (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, member_id VARCHAR(64) NOT NULL, invite_code VARCHAR(100) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), revoked_at DATETIME(3) NULL, UNIQUE KEY uq_referral_invite_code (guild_id,invite_code), KEY ix_referral_invites_member (guild_id,member_id,revoked_at), CONSTRAINT fk_referral_invites_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_referral_invites_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rewards (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, name VARCHAR(190) NOT NULL, description TEXT NOT NULL, image_url TEXT NULL, cost_overcredits INT NOT NULL, stock INT NULL, eligibility TEXT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), KEY ix_rewards_guild_active (guild_id,active), CONSTRAINT fk_rewards_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS reward_claims (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, reward_id VARCHAR(64) NOT NULL, member_id VARCHAR(64) NOT NULL, status ENUM('PENDING','APPROVED','REJECTED','FULFILLED','CANCELLED') NOT NULL DEFAULT 'PENDING', cost_overcredits INT NOT NULL, idempotency_key VARCHAR(190) NOT NULL, reviewed_by VARCHAR(20) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_reward_claim_idempotency (idempotency_key), KEY ix_reward_claims_member (guild_id,member_id,created_at), CONSTRAINT fk_reward_claims_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_reward_claims_reward FOREIGN KEY (reward_id) REFERENCES rewards(id), CONSTRAINT fk_reward_claims_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS achievements (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, achievement_key VARCHAR(100) NOT NULL, name VARCHAR(190) NOT NULL, description TEXT NOT NULL, kind VARCHAR(40) NOT NULL, threshold INT NOT NULL DEFAULT 1, overpoints_reward INT NOT NULL DEFAULT 0, overcredits_reward INT NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_achievements_key (guild_id,achievement_key), CONSTRAINT fk_achievements_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS member_achievements (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, member_id VARCHAR(64) NOT NULL, achievement_id VARCHAR(64) NOT NULL, awarded_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_member_achievement (member_id,achievement_id), CONSTRAINT fk_member_achievements_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_member_achievements_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE, CONSTRAINT fk_member_achievements_achievement FOREIGN KEY (achievement_id) REFERENCES achievements(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS daily_checkins (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, member_id VARCHAR(64) NOT NULL, checkin_date DATE NOT NULL, streak INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_daily_checkin (member_id,checkin_date), KEY ix_checkins_guild_date (guild_id,checkin_date), CONSTRAINT fk_checkins_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_checkins_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS leaderboard_snapshots (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, period VARCHAR(20) NOT NULL, category VARCHAR(80) NOT NULL, period_key VARCHAR(40) NOT NULL, member_id VARCHAR(64) NOT NULL, rank_position INT NOT NULL, score BIGINT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_leaderboard_snapshot (guild_id,period,category,period_key,member_id), KEY ix_leaderboard_rank (guild_id,period,category,period_key,rank_position), CONSTRAINT fk_leaderboard_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_leaderboard_member FOREIGN KEY (member_id) REFERENCES discord_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tickets (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, ticket_number BIGINT NOT NULL AUTO_INCREMENT, category VARCHAR(100) NOT NULL, channel_id VARCHAR(20) NULL, member_id VARCHAR(64) NOT NULL, status ENUM('OPEN','CLAIMED','CLOSED','ARCHIVED') NOT NULL DEFAULT 'OPEN', claimed_by VARCHAR(20) NULL, rating INT NULL, first_response_at DATETIME(3) NULL, closed_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uq_ticket_number (ticket_number), UNIQUE KEY uq_ticket_channel (guild_id,channel_id), KEY ix_tickets_guild_status (guild_id,status,created_at), CONSTRAINT fk_tickets_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_tickets_member FOREIGN KEY (member_id) REFERENCES discord_members(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ticket_messages (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, ticket_id VARCHAR(64) NOT NULL, author_id VARCHAR(20) NOT NULL, content TEXT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY ix_ticket_messages_ticket (ticket_id,created_at), CONSTRAINT fk_ticket_messages_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_ticket_messages_ticket FOREIGN KEY (ticket_id) REFERENCES tickets(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS moderation_actions (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, target_member_id VARCHAR(64) NOT NULL, actor_id VARCHAR(20) NOT NULL, action_type VARCHAR(40) NOT NULL, reason TEXT NULL, duration_minutes INT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY ix_moderation_target (guild_id,target_member_id,created_at), KEY ix_moderation_actor (guild_id,actor_id,created_at), CONSTRAINT fk_moderation_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id), CONSTRAINT fk_moderation_target FOREIGN KEY (target_member_id) REFERENCES discord_members(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS x_posts (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, post_id VARCHAR(40) NOT NULL, author_username VARCHAR(100) NOT NULL, post_text TEXT NOT NULL, url TEXT NOT NULL, media_urls JSON NULL, is_reply BOOLEAN NOT NULL DEFAULT FALSE, is_repost BOOLEAN NOT NULL DEFAULT FALSE, announced_at DATETIME(3) NULL, announced_channel_id VARCHAR(20) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_x_post (guild_id,post_id), KEY ix_x_posts_created (guild_id,created_at), CONSTRAINT fk_x_posts_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS bot_configuration (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, config_key VARCHAR(120) NOT NULL, config_value JSON NOT NULL, updated_by VARCHAR(20) NULL, updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uq_bot_config (guild_id,config_key), CONSTRAINT fk_bot_config_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, actor_id VARCHAR(20) NULL, action VARCHAR(120) NOT NULL, entity_type VARCHAR(120) NULL, entity_id VARCHAR(190) NULL, details JSON NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY ix_audit_actor_date (guild_id,actor_id,created_at), KEY ix_audit_entity (guild_id,entity_type,entity_id,created_at), CONSTRAINT fk_audit_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_records (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, record_type ENUM('SUGGESTION','REPORT','APPEAL','VOUCH','BLACKLIST','TEMP_ROLE','REMINDER') NOT NULL, status VARCHAR(40) NULL, subject_id VARCHAR(20) NULL, actor_id VARCHAR(20) NULL, payload JSON NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), KEY ix_community_records_type (guild_id,record_type,status,created_at), CONSTRAINT fk_community_records_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS invite_tracking (id VARCHAR(64) NOT NULL PRIMARY KEY, guild_id VARCHAR(20) NOT NULL, invite_code VARCHAR(100) NOT NULL, inviter_id VARCHAR(20) NULL, uses INT NOT NULL DEFAULT 0, payload JSON NULL, updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uq_invite_tracking (guild_id,invite_code), CONSTRAINT fk_invite_tracking_guild FOREIGN KEY (guild_id) REFERENCES guilds(guild_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;